/* ------------------------------------------------------------------ */
/* Components                                                          */
/* ------------------------------------------------------------------ */

var CMP = {};

function componentize(page, node, name, description, x, y) {
  var made = null;
  trySet("componentize " + name, function () {
    page.appendChild(node);
    node.x = x; node.y = y;
    made = figma.createComponentFromNode(node);
    made.name = name;
    if (description) made.description = description;
  });
  return made;
}

/*
 * Every use goes through here. If the component is missing, or an override
 * cannot find its layer, the page still gets a correct element built from the
 * same function the master was built from — a broken instance never costs the
 * whole page.
 */
function instantiate(comp, overrides, fallback) {
  if (!comp) return fallback();
  var inst = null;
  try {
    inst = comp.createInstance();
    for (var name in overrides) {
      var wanted = name;
      var t = inst.findOne(function (n) { return n.type === "TEXT" && n.name === wanted; });
      if (!t) throw new Error("missing layer " + wanted);
      t.characters = overrides[wanted];
    }
  } catch (e) {
    WARNINGS.push("instance " + name + ": " + (e && e.message ? e.message : String(e)));
    if (inst) { try { inst.remove(); } catch (e2) {} }
    return fallback();
  }
  return inst;
}

function buildComponents(page) {
  CMP.chip = componentize(page, chipNode(COPY.badges[0], false), "Chip",
    "תגית עובדה בהירו. החליפו את שכבת Label.", 0, 0);

  CMP.cta = componentize(page, ctaNode(COPY.ctaShort, false), "CTA / Primary",
    "כפתור הפעולה הראשי. גרדיאנט זהב עם טקסט בדיו הכהה.", 0, 120);

  CMP.stat = componentize(page, statNode(COPY.host.stats[0].value, COPY.host.stats[0].suffix,
    COPY.host.stats[0].label, false), "Stat", "מספר + סיומת + כיתוב.", 400, 0);

  CMP.field = componentize(page, fieldNode(UI_TEXT.fieldName, false), "Field",
    "שדה טופס. החליפו את שכבת Label.", 700, 0);

  CMP.card = componentize(page, curriculumCard("01", COPY.curriculum.items[0].title,
    COPY.curriculum.items[0].body, false), "Curriculum Card",
    "כרטיס ממוספר בסקשן „מה נלמד בהדרכה”.", 0, 260);

  return CMP;
}

function curriculumCard(num, title, body, mobile) {
  var card = frame("Curriculum Card", "HORIZONTAL", {
    itemSpacing: 18, cornerRadius: 32, counterAxisAlignItems: "MIN",
    fills: [paint("surface/shell")],
    strokes: [paint("text/ink", 0.1)], strokeWeight: 1,
    effects: [shadow("#0a2b30", 0.07, 12, 26)]
  });
  pad(card, mobile ? 22 : 28, mobile ? 20 : 28);
  var col = frame("Copy", "VERTICAL", { itemSpacing: 8 });
  col.appendChild(text(title, "h3", { mobile: mobile, name: "Title" }));
  addWrap(col, text(body, "bodyM", { mobile: mobile, color: "text/ink-soft", name: "Body" }), 320);
  var n = text(num, "statVal", { mobile: mobile, align: "CENTER", name: "Number" });
  n.fills = [paint("accent/gold-dp", 0.55)];
  // Reading order: the numeral is read first, so it sits on the right.
  appendRTL(card, [n, col]);
  fill(col);
  card.resize(mobile ? 340 : 560, card.height);
  return card;
}

function forkCard(data, positive, mobile) {
  var card = frame(positive ? "Fork Card / Connections" : "Fork Card / Long way", "VERTICAL", {
    itemSpacing: 18, cornerRadius: 32,
    fills: [positive ? paint("surface/shell") : paint("surface/sand")],
    strokes: [positive ? paint("accent/gold-dp", 0.45) : paint("text/ink", 0.1)],
    strokeWeight: 1,
    counterAxisAlignItems: "MAX",
    effects: positive ? [shadow("#805c23", 0.28, 20, 44)] : []
  });
  pad(card, mobile ? 26 : 34, mobile ? 22 : 34);

  card.appendChild(text(data.label, "eyebrow", {
    mobile: mobile, color: positive ? "text/gold-ink" : "text/ink-soft", name: "Label"
  }));
  addWrap(card, text(data.body, "bodyL", {
    mobile: mobile, color: positive ? "text/ink" : "text/ink-soft", name: "Body"
  }), 420);

  var rule = divider(420);
  card.appendChild(rule);
  fill(rule);

  var points = frame("Points", "VERTICAL", { itemSpacing: 14, counterAxisAlignItems: "MAX" });
  for (var i = 0; i < data.points.length; i++) {
    var row = pointRow(data.points[i], positive, mobile);
    points.appendChild(row);
    fill(row);
  }
  card.appendChild(points);
  fill(points);
  return card;
}

function wordmarkNode(mobile, small) {
  var w = frame("Wordmark", "VERTICAL", { itemSpacing: 6, counterAxisAlignItems: "MAX" });
  var n = text(SITE.name, "wordmark", { mobile: mobile, name: "Name" });
  n.fills = [goldGradientDeep()];
  if (small) n.fontSize = 18;
  w.appendChild(n);
  if (!small) {
    var row = frame("Tagline", "HORIZONTAL", { itemSpacing: 8, counterAxisAlignItems: "CENTER" });
    var kids = [text(SITE.roleParts[0], "eyebrow", { mobile: mobile, color: "text/gold-ink", name: "Part A" })];
    var star = brandStar(9, "#805c23");
    if (star) kids.push(star);
    kids.push(text(SITE.roleParts[1], "eyebrow", { mobile: mobile, color: "text/gold-ink", name: "Part B" }));
    appendRTL(row, kids);
    w.appendChild(row);
  }
  return w;
}

/* ------------------------------------------------------------------ */
/* Sections                                                            */
/* ------------------------------------------------------------------ */

function section(name, ctx, o) {
  var s = frame(name, "VERTICAL", o);
  s.counterAxisAlignItems = "CENTER";
  s.paddingLeft = ctx.padX;
  s.paddingRight = ctx.padX;
  return s;
}

function column(width, o) {
  return fixedWidth(frame("Content", "VERTICAL", o), width);
}

function headingPair(col, line1, line2, ctx, align) {
  var h = frame("Heading", "VERTICAL", { itemSpacing: 2, counterAxisAlignItems: align === "CENTER" ? "CENTER" : "MAX" });
  var a = text(line1, "h2", { mobile: ctx.mobile, align: align, name: "Line 1" });
  var b = text(line2, "h2", { mobile: ctx.mobile, align: align, name: "Line 2" });
  b.fills = [goldGradientDeep()];
  addWrap(h, a, col.width - 8);
  addWrap(h, b, col.width - 8);
  col.appendChild(h);
  fill(h);
  return h;
}

function heroSection(ctx) {
  var s = section("Hero", ctx, {
    paddingTop: ctx.mobile ? 32 : 56, paddingBottom: ctx.mobile ? 64 : 88,
    itemSpacing: ctx.mobile ? 40 : 56, fills: [paint("surface/ivory")]
  });
  var col = column(ctx.wide, { itemSpacing: ctx.mobile ? 40 : 56 });

  var bar = frame("Top bar", "HORIZONTAL", {
    counterAxisAlignItems: "CENTER", primaryAxisAlignItems: "SPACE_BETWEEN"
  });
  appendRTL(bar, [wordmarkNode(ctx.mobile, false), ghostCtaNode(COPY.ctaShort, ctx.mobile)]);
  col.appendChild(bar);
  fill(bar);

  var copy = frame("Copy", "VERTICAL", { itemSpacing: ctx.mobile ? 24 : 30, counterAxisAlignItems: "MAX" });
  var copyW = ctx.mobile ? ctx.content : 660;
  fixedWidth(copy, copyW);

  var badge = frame("Eyebrow badge", "HORIZONTAL", {
    cornerRadius: 999, counterAxisAlignItems: "CENTER", itemSpacing: 8,
    fills: [paint("surface/shell")], strokes: [paint("accent/gold-dp", 0.4)], strokeWeight: 1
  });
  pad(badge, 9, 16);
  var star = brandStar(11, "#805c23");
  appendRTL(badge, star
    ? [text(COPY.eyebrow, "chip", { mobile: ctx.mobile, color: "text/gold-ink", name: "Label" }), star]
    : [text(COPY.eyebrow, "chip", { mobile: ctx.mobile, color: "text/gold-ink", name: "Label" })]);
  copy.appendChild(badge);

  var h1 = frame("Headline", "VERTICAL", { itemSpacing: 0, counterAxisAlignItems: "MAX" });
  for (var i = 0; i < COPY.title.length; i++) {
    var line = COPY.title[i];
    var t = text(line.text, "h1", { mobile: ctx.mobile, name: "Line " + (i + 1) });
    if (line.gold) t.fills = [goldGradientDeep()];
    addWrap(h1, t, copyW);
  }
  copy.appendChild(h1);
  fill(h1);

  var lede = frame("Lede", "VERTICAL", {});
  lede.paddingRight = 20;
  trySet("lede rule", function () {
    lede.strokes = [paint("accent/gold-dp", 0.7)];
    lede.strokeTopWeight = 0; lede.strokeBottomWeight = 0; lede.strokeLeftWeight = 0; lede.strokeRightWeight = 2;
  });
  addWrap(lede, text(COPY.lede, "lede", { mobile: ctx.mobile, color: "text/gold-ink", name: "Lede" }), copyW - 24);
  copy.appendChild(lede);
  fill(lede);

  if (ctx.mobile) {
    var webM = null;
    trySet("web mobile", function () {
      webM = figma.createNodeFromSvg(webSvg(ctx.content, Math.round(ctx.content * 760 / 900)));
      webM.name = "Connection Web";
    });
    if (webM) copy.appendChild(webM);
  }

  var chips = frame("Facts", "HORIZONTAL", { itemSpacing: 10, counterAxisSpacing: 10, layoutWrap: "WRAP" });
  var chipNodes = [];
  for (var c = 0; c < COPY.badges.length; c++) {
    (function (label) {
      chipNodes.push(instantiate(CMP.chip, { Label: label }, function () { return chipNode(label, ctx.mobile); }));
    })(COPY.badges[c]);
  }
  appendRTL(chips, chipNodes);
  copy.appendChild(chips);
  fill(chips);

  copy.appendChild(instantiate(CMP.cta, { Label: COPY.ctaPrimary },
    function () { return ctaNode(COPY.ctaPrimary, ctx.mobile); }));

  if (ctx.mobile) {
    col.appendChild(copy);
    fill(copy);
  } else {
    var body = frame("Hero body", "HORIZONTAL", { itemSpacing: 40, counterAxisAlignItems: "CENTER" });
    var web = null;
    trySet("web desktop", function () {
      web = figma.createNodeFromSvg(webSvg(560, 470));
      web.name = "Connection Web";
    });
    appendRTL(body, web ? [copy, web] : [copy]);
    col.appendChild(body);
    fill(body);
  }

  s.appendChild(col);
  return s;
}

function invitationSection(ctx) {
  var s = section("Invitation", ctx, {
    paddingTop: ctx.mobile ? 64 : 96, paddingBottom: ctx.mobile ? 64 : 96,
    fills: [paint("surface/sand")]
  });
  var col = column(Math.min(760, ctx.content), { itemSpacing: 24, counterAxisAlignItems: "CENTER" });

  col.appendChild(eyebrowNode(COPY.invitation.eyebrow, ctx.mobile, false));
  headingPair(col, COPY.invitation.title, COPY.invitation.titleAccent, ctx, "CENTER");

  for (var i = 0; i < COPY.invitation.paragraphs.length; i++) {
    addWrap(col, text(COPY.invitation.paragraphs[i], "bodyL", {
      mobile: ctx.mobile, color: "text/ink-soft", align: "CENTER", name: "Paragraph " + (i + 1)
    }), col.width);
  }

  var banner = frame("Topic banner", "VERTICAL", {
    itemSpacing: 12, cornerRadius: 32, counterAxisAlignItems: "CENTER",
    fills: [paint("surface/shell")], strokes: [paint("accent/gold-dp", 0.4)], strokeWeight: 1
  });
  pad(banner, ctx.mobile ? 24 : 28, ctx.mobile ? 28 : 48);
  banner.appendChild(text(UI_TEXT.topic, "eyebrow", { mobile: ctx.mobile, color: "text/gold-ink", align: "CENTER", name: "Kicker" }));
  var bt = text(COPY.invitation.banner, "lede", { mobile: ctx.mobile, align: "CENTER", name: "Topic" });
  bt.fills = [goldGradientDeep()];
  banner.appendChild(bt);
  col.appendChild(banner);

  s.appendChild(col);
  return s;
}

function forkSection(ctx) {
  var s = section("Two ways to grow", ctx, {
    paddingTop: ctx.mobile ? 64 : 96, paddingBottom: ctx.mobile ? 64 : 96,
    fills: [paint("surface/ivory")]
  });
  var col = column(ctx.content, { itemSpacing: ctx.mobile ? 36 : 52, counterAxisAlignItems: "CENTER" });

  var head = frame("Head", "VERTICAL", { itemSpacing: 20, counterAxisAlignItems: "CENTER" });
  col.appendChild(head);
  fill(head);
  head.appendChild(eyebrowNode(COPY.fork.eyebrow, ctx.mobile, true));
  headingPair(head, COPY.fork.title, COPY.fork.titleAccent, ctx, "CENTER");

  var row = frame("Cards", ctx.mobile ? "VERTICAL" : "HORIZONTAL", { itemSpacing: 20 });
  col.appendChild(row);
  fill(row);
  // Long way first in reading order, so it lands on the right.
  var hard = forkCard(COPY.fork.hard, false, ctx.mobile);
  var smart = forkCard(COPY.fork.smart, true, ctx.mobile);
  appendRTL(row, [hard, smart]);
  fill(hard); fill(smart);

  s.appendChild(col);
  return s;
}

function curriculumSection(ctx) {
  var s = section("Curriculum", ctx, {
    paddingTop: ctx.mobile ? 64 : 96, paddingBottom: ctx.mobile ? 64 : 96,
    fills: [paint("surface/sand")]
  });
  var col = column(ctx.content, { itemSpacing: ctx.mobile ? 36 : 52, counterAxisAlignItems: "CENTER" });

  var head = frame("Head", "VERTICAL", { itemSpacing: 20, counterAxisAlignItems: "CENTER" });
  col.appendChild(head);
  fill(head);
  head.appendChild(eyebrowNode(COPY.curriculum.eyebrow, ctx.mobile, true));
  headingPair(head, COPY.curriculum.title, COPY.curriculum.titleAccent, ctx, "CENTER");

  var grid = frame("Grid", "VERTICAL", { itemSpacing: 20 });
  col.appendChild(grid);
  fill(grid);

  var items = COPY.curriculum.items;
  function card(i) {
    var num = (i + 1 < 10 ? "0" : "") + (i + 1);
    var item = items[i];
    return instantiate(CMP.card,
      { Number: num, Title: item.title, Body: item.body },
      function () { return curriculumCard(num, item.title, item.body, ctx.mobile); });
  }

  if (ctx.mobile) {
    for (var i = 0; i < items.length; i++) {
      var c = card(i);
      grid.appendChild(c);
      fill(c);
    }
  } else {
    for (var r = 0; r < 2; r++) {
      var row = frame("Row " + (r + 1), "HORIZONTAL", { itemSpacing: 20 });
      grid.appendChild(row);
      fill(row);
      var left = card(r * 2 + 1), right = card(r * 2);
      appendRTL(row, [right, left]);
      fill(right); fill(left);
    }
    // The fifth card sits alone; centring it keeps the grid from looking
    // like it lost one.
    var last = frame("Row 3", "HORIZONTAL", { primaryAxisAlignItems: "CENTER" });
    grid.appendChild(last);
    fill(last);
    var five = card(4);
    last.appendChild(five);
  }

  addWrap(col, text(COPY.curriculum.more, "chip", {
    mobile: ctx.mobile, color: "text/gold-ink", align: "CENTER", name: "More"
  }), col.width);

  s.appendChild(col);
  return s;
}

function hostSection(ctx) {
  var s = section("Host", ctx, {
    paddingTop: ctx.mobile ? 64 : 96, paddingBottom: ctx.mobile ? 64 : 96,
    fills: [paint("surface/ivory")]
  });
  var col = column(ctx.content, { itemSpacing: 40 });

  var portrait = frame("Portrait", null, {
    cornerRadius: 44, strokes: [paint("accent/gold-dp", 0.3)], strokeWeight: 1, clipsContent: true
  });
  var side = ctx.mobile ? Math.min(320, ctx.content) : 420;
  portrait.resize(side, side);
  trySet("portrait fill", function () {
    portrait.fills = PORTRAIT_HASH
      ? [{ type: "IMAGE", imageHash: PORTRAIT_HASH, scaleMode: "FILL" }]
      : [paint("surface/sand")];
  });

  var copy = frame("Copy", "VERTICAL", { itemSpacing: 18, counterAxisAlignItems: "MAX" });

  var body = frame("Host body", ctx.mobile ? "VERTICAL" : "HORIZONTAL", {
    itemSpacing: ctx.mobile ? 32 : 56,
    counterAxisAlignItems: "CENTER"
  });
  col.appendChild(body);
  fill(body);
  appendRTL(body, [portrait, copy]);
  if (!ctx.mobile) fill(copy); else fill(copy);

  copy.appendChild(eyebrowNode(COPY.host.eyebrow, ctx.mobile, true));
  var nm = text(COPY.host.name, "h2", { mobile: ctx.mobile, name: "Name" });
  copy.appendChild(nm);
  copy.appendChild(text(COPY.host.role, "eyebrow", { mobile: ctx.mobile, color: "text/gold-ink", name: "Role" }));

  var textW = ctx.mobile ? ctx.content : ctx.content - side - 56;
  for (var i = 0; i < COPY.host.body.length; i++) {
    addWrap(copy, text(COPY.host.body[i], "bodyM", {
      mobile: ctx.mobile, color: "text/ink-soft", name: "Paragraph " + (i + 1)
    }), textW);
  }

  var stats = frame("Stats", "HORIZONTAL", { itemSpacing: 20, counterAxisSpacing: 20, layoutWrap: "WRAP" });
  copy.appendChild(stats);
  fill(stats);
  var nodes = [];
  for (var k = 0; k < COPY.host.stats.length; k++) {
    (function (st) {
      nodes.push(instantiate(CMP.stat, { Value: st.value, Suffix: st.suffix, Caption: st.label },
        function () { return statNode(st.value, st.suffix, st.label, ctx.mobile); }));
    })(COPY.host.stats[k]);
  }
  appendRTL(stats, nodes);

  s.appendChild(col);
  return s;
}

function registerSection(ctx) {
  var s = section("Registration", ctx, {
    paddingTop: ctx.mobile ? 64 : 96, paddingBottom: ctx.mobile ? 64 : 96,
    fills: [paint("surface/sand")]
  });
  var col = column(Math.min(640, ctx.content), { itemSpacing: 28, counterAxisAlignItems: "CENTER" });

  col.appendChild(chipNode(COPY.form.eyebrow, ctx.mobile));
  headingPair(col, COPY.form.title, COPY.form.titleAccent, ctx, "CENTER");
  addWrap(col, text(COPY.form.sub, "bodyM", {
    mobile: ctx.mobile, color: "text/ink-soft", align: "CENTER", name: "Sub"
  }), col.width);

  var card = frame("Form card", "VERTICAL", {
    itemSpacing: 20, cornerRadius: 44,
    fills: [paint("surface/shell")], strokes: [paint("text/ink", 0.1)], strokeWeight: 1,
    effects: [shadow("#0a2b30", 0.1, 22, 46)]
  });
  pad(card, ctx.mobile ? 28 : 40, ctx.mobile ? 22 : 40);
  col.appendChild(card);
  fill(card);

  function field(label) {
    return instantiate(CMP.field, { Label: label }, function () { return fieldNode(label, ctx.mobile); });
  }

  var name = field(UI_TEXT.fieldName);
  card.appendChild(name);
  fill(name);

  var pair = frame("Row", ctx.mobile ? "VERTICAL" : "HORIZONTAL", { itemSpacing: 16 });
  card.appendChild(pair);
  fill(pair);
  var phone = field(UI_TEXT.fieldPhone), email = field(UI_TEXT.fieldEmail);
  appendRTL(pair, [phone, email]);
  fill(phone); fill(email);

  var cta = instantiate(CMP.cta, { Label: COPY.form.submit },
    function () { return ctaNode(COPY.form.submit, ctx.mobile); });
  card.appendChild(cta);
  fill(cta);

  addWrap(card, text(COPY.form.consent, "bodyS", {
    mobile: ctx.mobile, color: "text/ink-soft", align: "CENTER", name: "Consent"
  }), col.width - 80);

  var closing = frame("Closing", "VERTICAL", { itemSpacing: 12, counterAxisAlignItems: "CENTER" });
  col.appendChild(closing);
  fill(closing);
  var c1 = text(COPY.closing.title, "h3", { mobile: ctx.mobile, align: "CENTER", name: "Line 1" });
  c1.fontSize = ctx.mobile ? 22 : 26;
  var c2 = text(COPY.closing.titleAccent, "h3", { mobile: ctx.mobile, align: "CENTER", name: "Line 2" });
  c2.fontSize = ctx.mobile ? 22 : 26;
  c2.fills = [goldGradientDeep()];
  addWrap(closing, c1, col.width);
  addWrap(closing, c2, col.width);
  addWrap(closing, text(COPY.closing.body, "bodyM", {
    mobile: ctx.mobile, color: "text/ink-soft", align: "CENTER", name: "Body"
  }), col.width);

  s.appendChild(col);
  return s;
}

function footerSection(ctx) {
  var s = frame("Footer", ctx.mobile ? "VERTICAL" : "HORIZONTAL", {
    itemSpacing: 16, fills: [paint("surface/ivory")],
    counterAxisAlignItems: "CENTER",
    primaryAxisAlignItems: ctx.mobile ? "CENTER" : "SPACE_BETWEEN"
  });
  pad(s, 32, ctx.padX);
  trySet("footer rule", function () {
    s.strokes = [paint("text/ink", 0.1)];
    s.strokeBottomWeight = 0; s.strokeLeftWeight = 0; s.strokeRightWeight = 0; s.strokeTopWeight = 1;
  });

  var links = frame("Links", "HORIZONTAL", { itemSpacing: 24, counterAxisAlignItems: "CENTER" });
  appendRTL(links, [
    text(UI_TEXT.terms, "bodyS", { mobile: ctx.mobile, color: "text/ink-soft", name: "Terms" }),
    text(UI_TEXT.privacy, "bodyS", { mobile: ctx.mobile, color: "text/ink-soft", name: "Privacy" }),
    text(UI_TEXT.accessibility, "bodyS", { mobile: ctx.mobile, color: "text/ink-soft", name: "Accessibility" }),
    text(SITE.email, "bodyS", { mobile: ctx.mobile, color: "text/ink-soft", name: "Email" })
  ]);

  appendRTL(s, [wordmarkNode(ctx.mobile, true), links]);
  return s;
}

/* ------------------------------------------------------------------ */
/* Page assembly                                                       */
/* ------------------------------------------------------------------ */

function buildPage(ctx) {
  var root = frame(ctx.name, "VERTICAL", { itemSpacing: 0, fills: [paint("surface/ivory")], clipsContent: true });
  fixedWidth(root, ctx.width);

  var sections = [
    heroSection(ctx), invitationSection(ctx), forkSection(ctx),
    curriculumSection(ctx), hostSection(ctx), registerSection(ctx), footerSection(ctx)
  ];
  for (var i = 0; i < sections.length; i++) {
    root.appendChild(sections[i]);
    fill(sections[i]);
  }
  applyFills();
  return root;
}

/*
 * The confirmation the form swaps itself for. It never coexists with the form
 * on screen, so it gets its own small frame rather than a spot in the page.
 */
function successState() {
  var card = frame("Registration — success", "VERTICAL", {
    itemSpacing: 18, cornerRadius: 44, counterAxisAlignItems: "CENTER",
    fills: [paint("surface/shell")],
    strokes: [paint("accent/gold-dp", 0.4)], strokeWeight: 1,
    effects: [shadow("#805c23", 0.28, 20, 44)]
  });
  pad(card, 56, 48);
  fixedWidth(card, 560);

  var ring = frame("Check", "HORIZONTAL", {
    cornerRadius: 999, counterAxisAlignItems: "CENTER", primaryAxisAlignItems: "CENTER",
    fills: [paint("surface/ivory")], strokes: [paint("accent/gold-dp", 0.45)], strokeWeight: 1
  });
  ring.resize(64, 64);
  ring.primaryAxisSizingMode = "FIXED";
  ring.counterAxisSizingMode = "FIXED";
  var mark = svg(icon(P_CHECK, 30, "#805c23"), 30);
  if (mark) ring.appendChild(mark);
  card.appendChild(ring);

  var title = text(COPY.form.success.title, "h3", { align: "CENTER", name: "Title" });
  title.fontSize = 28;
  title.fills = [goldGradientDeep()];
  addWrap(card, title, 460);
  addWrap(card, text(COPY.form.success.body, "bodyM", {
    color: "text/ink-soft", align: "CENTER", name: "Body"
  }), 460);

  applyFills();
  return card;
}

async function main() {
  await loadFonts();
  createTokens();
  createTextStyles();
  createPortraitImage();

  var componentsPage = figma.createPage();
  componentsPage.name = "רכיבים";
  var landing = figma.createPage();
  landing.name = "דף נחיתה — שת״פים";

  buildComponents(componentsPage);
  applyFills();

  var desktop = buildPage({
    name: "Landing — Desktop 1440", width: 1440, padX: 80, content: 1152, wide: 1280, mobile: false
  });
  landing.appendChild(desktop);
  desktop.x = 0; desktop.y = 0;

  var mobile = buildPage({
    name: "Landing — Mobile 390", width: 390, padX: 20, content: 350, wide: 350, mobile: true
  });
  landing.appendChild(mobile);
  mobile.x = 1600; mobile.y = 0;

  var success = successState();
  landing.appendChild(success);
  success.x = 2120; success.y = 0;

  if (typeof figma.setCurrentPageAsync === "function") await figma.setCurrentPageAsync(landing);
  else figma.currentPage = landing;

  trySet("viewport", function () {
    figma.currentPage.selection = [desktop];
    figma.viewport.scrollAndZoomIntoView([desktop, mobile, success]);
  });

  return { desktop: desktop.id, mobile: mobile.id, success: success.id };
}

main().then(function () {
  var msg = WARNINGS.length
    ? "הדף נבנה. " + WARNINGS.length + " אזהרות עיצוב (ראו קונסולה)."
    : "הדף נבנה בהצלחה ✓";
  if (WARNINGS.length) console.log("WARNINGS:\n" + WARNINGS.join("\n"));
  figma.closePlugin(msg);
}).catch(function (e) {
  console.log(e && e.stack ? e.stack : String(e));
  figma.closePlugin("שגיאה: " + (e && e.message ? e.message : String(e)));
});
